"use strict";
GUIDE_DATA_VI.sections.push({"id":"g46","part":5,"title":"Cuộc họp thông tin (Informative Meetings)","blocks":[{"level":1,"text":"Cuộc họp thông tin (Informative Meetings)"},{"level":2,"text":"Phổ biến thông tin, thông báo cho nhóm về những thông tin cần được lan truyền"},{"level":1,"text":"Các cuộc họp thông tin mang tính giáo dục hoặc thuyết phục"},{"level":1,"text":"Sử dụng các cuộc họp thông tin khi cần thiết và làm cho chúng tương tác nhất có thể"},{"level":1,"text":"3 phân loại con của cuộc họp thông tin"},{"level":2,"text":"Trình diễn và thuyết trình (Demonstrations and Presentations)"},{"level":2,"text":"Người thuyết trình chia sẻ các tính năng sản phẩm hoặc tổ chức đào tạo"},{"level":2,"text":"Các buổi trình diễn giúp kết quả của nhóm phù hợp với kỳ vọng của các bên liên quan (stakeholders)"},{"level":2,"text":"Cập nhật tình trạng (Status Updates)"},{"level":2,"text":"Cung cấp cập nhật về tiến độ dự án tại một thời điểm cụ thể, khác nhau về tần suất và chương trình nghị sự"},{"level":2,"text":"Các cuộc họp tình trạng giúp người tham dự cập nhật về dự án mà không tốn quá nhiều thời gian vào các chi tiết vụn vặt"},{"level":2,"text":"Họp đứng (Stand-up)"},{"level":2,"text":"Scrum sử dụng các cuộc họp đứng hằng ngày để giữ mọi thành viên nhóm cùng một nhịp"},{"level":2,"text":"Các cuộc họp đứng thường ngắn và thường kéo dài 15 phút hoặc ít hơn"},{"level":2,"text":"Mục đích là để các thành viên nhóm trao đổi thông tin nhanh chóng, giải quyết vấn đề và quay lại làm việc"}]},{"id":"g47","part":5,"title":"Cuộc họp quyết định (Decisive Meetings)","blocks":[{"level":1,"text":"Cuộc họp quyết định (Decisive Meeting) còn gọi là cuộc họp ra quyết định (decision-making meetings), nơi một hoặc nhiều người tham dự có thể đưa ra quyết định"},{"level":2,"text":"Cần cho phép các thành viên nhóm trao đổi thông tin, vì vậy hãy hướng tới một nhóm nhỏ hơn, có tính tương tác; nhóm tám thành viên hoặc ít hơn sẽ hiệu quả"},{"level":1,"text":"Mọi người thường không nhận ra khi nào mình cần đưa ra quyết định"},{"level":1,"text":"Các ví dụ về cuộc họp quyết định"},{"level":2,"text":"Giao việc (Task Setting)"},{"level":2,"text":"Giao việc cho từng cá nhân trong nhóm"},{"level":2,"text":"Điều hành dự án (Project Steering)"},{"level":2,"text":"Bao gồm quản lý dự án và các bên liên quan cấp điều hành"},{"level":2,"text":"Ủy ban điều hành (steering committee) đại diện cho tiếng nói của khách hàng và đóng vai trò là cơ quan quản trị của dự án mà không trực tiếp quản lý nó"},{"level":2,"text":"Họ giám sát tiến độ và các sản phẩm bàn giao (deliverables) của dự án"},{"level":2,"text":"PM có thể dùng loại cuộc họp này để đảm bảo các quyết định về tài trợ và thứ tự ưu tiên"},{"level":2,"text":"Cuộc họp tinh chỉnh (Refinement Meeting)"},{"level":2,"text":"Còn gọi là cuộc họp tinh chỉnh sản phẩm (product refinement) hoặc tinh chỉnh backlog (backlog refine meeting), là quá trình ưu tiên các ý tưởng có giá trị nhất để đưa vào kế hoạch"}]},{"id":"g48","part":5,"title":"Cuộc họp cộng tác (Collaborative Meetings)","blocks":[{"level":1,"text":"Các cuộc họp cộng tác (collaborative meetings) có tính tương tác rất cao"},{"level":2,"text":"Cần đủ người tham dự để tạo ra các ý tưởng đa dạng nhưng không quá nhiều đến mức mọi người không thể tham gia"},{"level":1,"text":"4 loại chính của cuộc họp cộng tác"},{"level":2,"text":"Nhóm tập trung (Focus Groups)"},{"level":2,"text":"Kỹ thuật nghiên cứu trong đó quản lý dự án tập hợp một nhóm khách hàng hoặc khách hàng tiềm năng để người tham dự chia sẻ trải nghiệm, nhận thức, nhu cầu và vấn đề liên quan đến một dự án hoặc sản phẩm"},{"level":2,"text":"Chúng thường có 6-12 người tham dự và được tổ chức trực tiếp hoặc trực tuyến, có chương trình nghị sự có cấu trúc, ví dụ như một danh sách câu hỏi được chuẩn bị sẵn"},{"level":2,"text":"PM điều phối và kiểm soát phiên họp, nhưng giá trị thực sự đến từ sự tương tác của người tham dự"},{"level":2,"text":"Giảm thiên lệch bằng cách giữ thái độ trung lập trong suốt quá trình hoặc mời một bên khách quan điều hành phiên họp"},{"level":2,"text":"Một số cách để điều phối một nhóm tập trung"},{"level":2,"text":"Một người điều hành (Single-moderator)"},{"level":2,"text":"Hai người điều hành (Dual-moderator)"},{"level":2,"text":"Hai người điều hành đối lập (Dueling-moderator)"},{"level":2,"text":"Nhóm tập trung hai chiều (Two-way Focus Groups)"},{"level":2,"text":"Cho phép một nhóm quan sát phiên họp của nhóm tập trung khác"},{"level":2,"text":"Nhóm tập trung người tham gia làm điều hành (Respondent-Moderator Focus Groups)"},{"level":2,"text":"Cho phép một nhóm quan sát phiên họp của nhóm tập trung khác"},{"level":2,"text":"Các bên liên quan có thể thu được góc nhìn vô giá từ các nhóm tập trung"},{"level":2,"text":"Hội thảo (Workshop)"},{"level":2,"text":"Phiên làm việc nơi một nhóm có chung sở thích tụ họp để trao đổi thông tin và tiến hành nghiên cứu"},{"level":2,"text":"Khi tạo chương trình nghị sự cho hội thảo, hãy bao gồm các mục tiêu rõ ràng mô tả những gì mọi người cần làm hoặc chuẩn bị cho cuộc họp"},{"level":2,"text":"Danh sách người tham dự đa dạng có thể gây ra vấn đề về lịch trình và thách thức động lực nhóm"},{"level":2,"text":"Đánh giá ứng dụng chung (Joint Application Review)"},{"level":2,"text":"Loại hội thảo đặc biệt nơi khách hàng tham gia vào quá trình thiết kế sản phẩm"},{"level":2,"text":"Nhóm phát triển có thể điều chỉnh cách tiếp cận nhanh chóng và với chi phí thấp hơn nhiều"},{"level":2,"text":"Động não (Brainstorming)"},{"level":2,"text":"Cho phép một nhóm tạo ra nhiều ý tưởng một cách nhanh chóng"},{"level":2,"text":"Các phiên động não thường là những sự kiện nhịp độ nhanh, nơi mọi người đều có thể tham gia và chúng thường khá vui vẻ, tất nhiên là theo chuẩn của các cuộc họp kinh doanh"},{"level":2,"text":"4 phân loại con của động não"},{"level":2,"text":"Nhanh (Rapid)"},{"level":2,"text":"Cho người tham dự 3-5 phút để viết ra các ý tưởng"},{"level":2,"text":"Đảo ngược (Reverse)"},{"level":2,"text":"Nhìn vấn đề từ các góc độ khác nhau"},{"level":2,"text":"Dừng-và-đi (Stop-and-Go)"},{"level":2,"text":"Giải quyết vấn đề số lượng lấn át chất lượng"},{"level":2,"text":"Vòng tròn (Round-Robin)"},{"level":2,"text":"Mang lại cho mọi người tiếng nói bình đẳng"}]},{"id":"g49","part":5,"title":"Tài liệu cuộc họp (Meeting Artifacts)","blocks":[{"level":1,"text":"Việc giữ sự ngăn nắp là rất quan trọng đối với một quản lý dự án"},{"level":1,"text":"Chương trình nghị sự của cuộc họp (Meeting Agenda)"},{"level":2,"text":"Bao gồm mục đích cuộc họp và lịch trình các hoạt động hoặc chủ đề cho cuộc họp"},{"level":2,"text":"Kỹ thuật POWER Start Agenda là một cách tuyệt vời để tạo chương trình nghị sự cho cuộc họp"},{"level":2,"text":"Mục đích (Purpose)"},{"level":2,"text":"Kết quả (Outcomes)"},{"level":2,"text":"Điều gì trong đó dành cho tôi (What's In It For Me - WIIFM)"},{"level":2,"text":"Sự tham gia (Engagement)"},{"level":2,"text":"Vai trò và trách nhiệm (Roles and Responsibilities)"},{"level":1,"text":"Khung thời gian (Timeboxes)"},{"level":2,"text":"Xác định thời gian nhóm sẽ dành cho mỗi chủ đề trong cuộc họp"},{"level":1,"text":"Các mục hành động (Action Items)"},{"level":2,"text":"Các công việc mà ai đó sẽ hoàn thành sau cuộc họp"},{"level":1,"text":"Biên bản họp (Meeting Minutes)"},{"level":2,"text":"Tạo hồ sơ bằng văn bản về các ý chính"},{"level":1,"text":"Theo dõi (Follow-Up)"},{"level":2,"text":"Email để chia sẻ biên bản họp và thông tin bổ sung"}]},{"id":"g50","part":5,"title":"Quản lý xung đột (Conflict Management)","blocks":[{"level":1,"text":"Xung đột là điều không thể tránh khỏi trong cả đời sống cá nhân và nghề nghiệp của chúng ta"},{"level":1,"text":"Một nhóm cần thời gian để ổn định và bình thường hóa"},{"level":1,"text":"Mô hình phát triển nhóm của Tuckman (Tuckman's Team and Group Development Model)"},{"level":2,"text":"Hình thành (Forming)"},{"level":2,"text":"Các thành viên gặp nhau lần đầu và bắt đầu làm quen, thăm dò lẫn nhau"},{"level":2,"text":"Xung đột (Storming)"},{"level":2,"text":"Mọi vấn đề trong quy trình, dù lớn hay nhỏ, đều bị khuếch đại và đặt câu hỏi trong giai đoạn này"},{"level":2,"text":"Ổn định (Norming)"},{"level":2,"text":"Các thành viên vượt qua khác biệt và tôn trọng lẫn nhau"},{"level":2,"text":"Hoạt động hiệu quả (Performing)"},{"level":2,"text":"Các thành viên biết cách làm việc cùng nhau và biết phải làm gì"},{"level":2,"text":"Giải tán (Adjourning)"},{"level":2,"text":"Nhóm tan rã và các thành viên chuyển sang các dự án mới"},{"level":1,"text":"2 loại xung đột"},{"level":2,"text":"Về nội dung (Substantive)"},{"level":2,"text":"Về cảm xúc (Emotional)"},{"level":1,"text":"Cả xung đột tích cực và tiêu cực đều cần được theo dõi và quản lý"},{"level":1,"text":"Các nguyên nhân phổ biến của xung đột"},{"level":2,"text":"Khác biệt tính cách là một yếu tố góp phần lớn"},{"level":2,"text":"Các vấn đề cá nhân và yếu tố bên ngoài cũng có thể góp phần"},{"level":2,"text":"Cạnh tranh về nguồn lực dự án xuất phát từ hạn chế ngân sách, hoặc có thể có các ưu tiên hoặc đề xuất mâu thuẫn"},{"level":2,"text":"Khác biệt trong phong cách viết có thể dẫn đến giao tiếp sai lệch và xung đột"},{"level":2,"text":"Mức độ trang trọng (Formality)"},{"level":2,"text":"Giọng điệu (Tone)"},{"level":2,"text":"Trình bày (Presentation)"},{"level":2,"text":"Khác biệt văn hóa (Cultural differences)"},{"level":2,"text":"Giọng điệu (Tone)"},{"level":2,"text":"Sự tinh tế (Subtlety)"},{"level":2,"text":"Lựa chọn từ ngữ (Word Choice)"},{"level":2,"text":"Khác biệt về khả năng biểu đạt, ngôn ngữ cơ thể và không gian cá nhân điển hình"},{"level":1,"text":"Làm thế nào để chúng ta giải quyết xung đột?"},{"level":2,"text":"Quản lý xung đột hiệu quả đòi hỏi quá trình rèn luyện suốt đời"},{"level":2,"text":"Bạn có thể quản lý và giải quyết xung đột bằng cách áp dụng năm chiến lược:"},{"level":2,"text":"Xoa dịu (Smoothing)"},{"level":2,"text":"Còn gọi là thích nghi (accommodating), chiến lược này cố gắng chuyển hướng các bên đang xung đột ra khỏi mâu thuẫn"},{"level":2,"text":"Ép buộc (Forcing)"},{"level":2,"text":"Còn gọi là áp đảo (dominating), chiến lược này quản lý xung đột bằng cách quyết định điều cần làm để khắc phục vấn đề, giống như một người độc đoán"},{"level":2,"text":"Thỏa hiệp (Compromising)"},{"level":2,"text":"Những người trong xung đột chia sẻ quan điểm của mình và nhượng bộ để thay đổi một điều gì đó nhưng vẫn giữ lại một phần ý tưởng của mình"},{"level":2,"text":"Hợp tác (Collaborating)"},{"level":2,"text":"Tránh né (Avoiding)"},{"level":2,"text":"Phớt lờ xung đột; hãy chọn phương án này nếu vấn đề quá nhỏ không đáng giải quyết và không ảnh hưởng đến hiệu suất của nhóm"},{"level":1,"text":"Nhận diện xung đột sớm là chìa khóa để quản lý xung đột thành công"},{"level":1,"text":"9 giai đoạn leo thang xung đột"},{"level":2,"text":"Giai đoạn 1-3 (Stages 1-3)"},{"level":2,"text":"Các bên vẫn muốn thống nhất với nhau và tìm giải pháp cùng thắng (win-win)"},{"level":2,"text":"Giai đoạn 4-6 (Stages 4-6)"},{"level":2,"text":"Xung đột leo thang thành kịch bản được-mất (win-lose) và các bên tranh giành quyền kiểm soát"},{"level":2,"text":"Giai đoạn 7-9 (Stages 7-9)"},{"level":2,"text":"Tình huống hoàn toàn cùng thua (lose-lose), những người trong xung đột không thể tự mình giải quyết. Công cụ quản lý dự án (Project Management Tools)"}]},{"id":"g51","part":6,"title":"Công cụ quản lý dự án (Project Management Tools)","blocks":[{"level":1,"text":"Phần mềm tốt có thể giảm chi phí gián tiếp (overhead) của bạn và tạo ra các kênh giao tiếp tốt hơn"},{"level":1,"text":"Các quản lý dự án cần điều phối các cuộc họp và tương tác, cũng như sử dụng nhiều phương tiện và công cụ họp khác nhau"},{"level":2,"text":"Công cụ lịch (Calendaring Tools)"},{"level":2,"text":"Nền tảng hội nghị (Conferencing Platforms)"},{"level":2,"text":"Công cụ khảo sát và thăm dò (Survey and Polling Tools)"},{"level":2,"text":"Ấn phẩm in (Print Media)"},{"level":1,"text":"Mọi người có các phong cách học khác nhau, một số học qua thính giác, một số học qua xúc giác và một số học qua thị giác"},{"level":1,"text":"Các quản lý dự án thường sử dụng sơ đồ"},{"level":2,"text":"Biểu đồ Gantt (Gantt Charts)"},{"level":2,"text":"Lưu đồ (Flow Charts)"},{"level":2,"text":"Cây quyết định (Decision Trees)"},{"level":2,"text":"Sơ đồ luồng dữ liệu (Data Flow Diagrams)"},{"level":2,"text":"Sơ đồ tư duy (Mind Maps)"},{"level":2,"text":"Sơ đồ tứ phân (Quadrant Diagrams)"},{"level":1,"text":"Các công cụ cộng tác rất cần thiết để quản lý dự án giao tiếp và làm việc với nhóm của mình"},{"level":2,"text":"Phần mềm chỉnh sửa đa tác giả (Multi-authoring editing software)"},{"level":2,"text":"Nền tảng chia sẻ tệp (File sharing platforms)"},{"level":2,"text":"Nền tảng quy trình công việc và chữ ký điện tử (Workflow and e-signature platforms)"},{"level":2,"text":"Cơ sở tri thức (Knowledge bases)"},{"level":2,"text":"Bảng trắng (Whiteboards)"},{"level":1,"text":"Các công cụ giao tiếp, như email, nhắn tin chat, SMS, giao tiếp trực tiếp, cuộc gọi điện thoại, hội nghị video và mạng xã hội, rất quan trọng để quản lý dự án kết nối với các thành viên nhóm"},{"level":1,"text":"Kế hoạch giao tiếp (Communication Plan)"},{"level":2,"text":"Phác thảo cách các bên liên quan và thành viên nhóm sẽ nhận được cập nhật dự án, đồng thời thiết lập các vòng giao tiếp định kỳ cho thông tin quan trọng và phản hồi"},{"level":2,"text":"Các thành phần chính của kế hoạch giao tiếp bao gồm"},{"level":2,"text":"Mục tiêu (Goals)"},{"level":2,"text":"Các bên liên quan (Stakeholders)"},{"level":2,"text":"Thành viên nhóm (Team members)"},{"level":2,"text":"Hiện vật (Artifacts)"},{"level":2,"text":"Kênh (Channels)"},{"level":2,"text":"Người nhận giao tiếp (Communication Recipients)"},{"level":2,"text":"Tần suất (Frequency)"},{"level":2,"text":"Kết quả (Outcomes)"},{"level":1,"text":"Kế hoạch leo thang (Escalation Plan)"},{"level":2,"text":"Giúp giải quyết các vấn đề của dự án bằng cách phác thảo các kịch bản vấn đề, các cấp độ leo thang, người chịu trách nhiệm và các yếu tố kích hoạt"}]},{"id":"g52","part":6,"title":"Các tùy chọn cài đặt (Installation Options)","blocks":[{"level":1,"text":"Các tùy chọn cài đặt ảnh hưởng đến tổng chi phí sở hữu (total cost of ownership)"},{"level":2,"text":"Dựa trên đám mây (Cloud-based)"},{"level":2,"text":"Cung cấp cho người dùng quyền truy cập ứng dụng qua trình duyệt Internet và thường được gọi là phần mềm trực tuyến (online software) hoặc cài đặt trực tuyến (online installations)"},{"level":2,"text":"Sử dụng phí định kỳ"},{"level":2,"text":"Chi phí vận hành (Operational expense)"},{"level":2,"text":"Tại chỗ (On-premise)"},{"level":2,"text":"Được cài đặt trên đám mây hoặc tại chỗ"},{"level":2,"text":"Khoản đầu tư ban đầu (Initial investment)"},{"level":2,"text":"Cài đặt cục bộ (Local Installation)"},{"level":2,"text":"Một biến thể của giải pháp tại chỗ và là mô hình phổ biến cho máy tính cá nhân"},{"level":2,"text":"Phần mềm được cài đặt trên thiết bị hiện có"},{"level":1,"text":"Các cân nhắc về quyền truy cập người dùng cho các tùy chọn cài đặt"},{"level":2,"text":"Phần mềm đám mây hoạt động trên nhiều thiết bị khác nhau qua trình duyệt Internet"},{"level":2,"text":"Giải pháp tại chỗ cho phép người dùng truy cập thông qua một ứng dụng trên các thiết bị"},{"level":2,"text":"Trong cài đặt cục bộ, người dùng truy cập phần mềm từ thiết bị mà nó được cài đặt"},{"level":1,"text":"Các tùy chọn cài đặt ảnh hưởng đến mô hình định giá như thế nào"},{"level":2,"text":"Dựa trên đám mây (Cloud-based)"},{"level":2,"text":"Sử dụng phí định kỳ"},{"level":2,"text":"Chi phí vận hành (Operational expense)"},{"level":2,"text":"Tại chỗ (On-premise)"},{"level":2,"text":"Khoản đầu tư ban đầu (Initial investment)"},{"level":2,"text":"Cài đặt cục bộ (Local Installation)"},{"level":2,"text":"Phần mềm được cài đặt trên thiết bị hiện có"},{"level":1,"text":"Ưu điểm của các tùy chọn cài đặt"},{"level":2,"text":"Giải pháp dựa trên đám mây là lựa chọn ít cần bảo trì"},{"level":2,"text":"Cài đặt tại chỗ cho phép các công ty kiểm soát hoàn toàn phần mềm đã cài đặt"},{"level":2,"text":"Tùy chọn cài đặt cục bộ cung cấp quyền truy cập phần mềm đáng tin cậy"},{"level":1,"text":"Nhược điểm của các tùy chọn cài đặt"},{"level":2,"text":"Đám mây có chi phí ngắn hạn thấp hơn nhưng chi phí dài hạn cao hơn"},{"level":2,"text":"Cài đặt cục bộ và tại chỗ yêu cầu mua trước một lượng lớn giấy phép phần mềm và phần cứng"},{"level":2,"text":"Sản phẩm phần mềm tại chỗ cần được bảo trì, giám sát và cập nhật"},{"level":2,"text":"Phần mềm trong cài đặt cục bộ chỉ khả dụng trên máy tính mà nó được tải về"},{"level":2,"text":"Cài đặt cục bộ yêu cầu dung lượng lưu trữ bổ sung trên mỗi thiết bị"}]},{"id":"g53","part":6,"title":"Công cụ họp (Meeting Tools)","blocks":[{"level":1,"text":"Các quản lý dự án cần điều phối các cuộc họp, hội thảo và các tương tác khác"},{"level":1,"text":"Công cụ lịch (Calendaring Tool)"},{"level":2,"text":"Đơn giản hóa quá trình lập lịch bằng cách quản lý lịch và thời gian biểu"},{"level":1,"text":"Các cuộc họp với nhóm phân tán về mặt địa lý được hưởng lợi từ việc sử dụng các nền tảng hội nghị"},{"level":1,"text":"Các công cụ khảo sát và thăm dò cho phép tương tác giữa người tham dự mà không cần ai cũng phải phát biểu"},{"level":2,"text":"Khảo sát và thăm dò là một cách tuyệt vời để tăng tương tác trong các cuộc họp hội nghị video"},{"level":1,"text":"Ấn phẩm in (Print Media)"},{"level":2,"text":"Các vật liệu vật lý, ví dụ như áp phích, bảng lật, tờ rơi quảng cáo và tài liệu đào tạo"}]},{"id":"g54","part":6,"title":"Công cụ năng suất (Productivity Tools)","blocks":[{"level":1,"text":"Các công cụ dự án giúp tạo hồ sơ về các hoạt động dự án và tình trạng của chúng, đồng thời giúp tự động hóa nhiều phép tính và tạo ra các báo cáo, bảng điều khiển (dashboards) có giá trị"},{"level":1,"text":"Hệ thống trợ giúp (Help Desk System)"},{"level":2,"text":"Người dùng gửi yêu cầu trong hệ thống, và các quy trình công việc tự động định tuyến yêu cầu đến cá nhân hoặc nhóm có thể giải quyết"},{"level":1,"text":"Hệ thống vé (ticketing systems) là công cụ tổ chức cực kỳ quan trọng, giúp chia nhỏ và ưu tiên công việc cần làm một cách có hệ thống"},{"level":1,"text":"Một số tính năng của phần mềm quản lý dự án"},{"level":2,"text":"Lập kế hoạch công việc (Task Planning)"},{"level":2,"text":"Tự động hóa quy trình công việc (Workflow Automation)"},{"level":2,"text":"Phân bổ nguồn lực (Resource Allocation)"},{"level":1,"text":"Các công cụ lập lịch có thể tự động tạo biểu đồ Gantt, rất hữu ích để giữ sự ngăn nắp"},{"level":1,"text":"Hãy nhớ rằng kết quả của bạn sẽ khác nhau khi bạn thử nghiệm các nền tảng phần mềm khác nhau"},{"level":1,"text":"Hãy cân nhắc sử dụng công cụ quản lý dự án cho các dự án của bạn"},{"level":1,"text":"Các công cụ năng suất khác nhau"},{"level":2,"text":"Trình soạn thảo văn bản (Text Editors)"},{"level":2,"text":"Chúng cho phép chỉnh sửa văn bản trong một tệp bằng cách thêm, xóa hoặc thay đổi ký tự, nhưng bạn không thể áp dụng bất kỳ định dạng nào"},{"level":2,"text":"Trình soạn thảo văn bản hữu ích để viết mã, ghi lại thông tin trong môi trường sạch và xóa định dạng khỏi văn bản"},{"level":2,"text":"Trình xử lý văn bản (Word Processors)"},{"level":2,"text":"Định dạng văn bản, chèn đối tượng và tạo tài liệu bắt mắt"},{"level":2,"text":"Bảng tính (Spreadsheets)"},{"level":2,"text":"Làm việc với dữ liệu trong bảng, sắp xếp và sửa đổi dữ liệu, thực hiện các phép tính toán và tạo biểu đồ"},{"level":2,"text":"Phần mềm thuyết trình và vẽ sơ đồ (Presentation and Diagramming Software)"},{"level":2,"text":"Tạo các bộ slide, là một chuỗi các trang trực quan kết hợp lại để kể một câu chuyện"},{"level":2,"text":"Liệt kê một số chủ đề mà bạn muốn thảo luận khi thuyết trình trước nhóm"}]},{"id":"g55","part":6,"title":"Các sơ đồ phổ biến (Common Diagrams)","blocks":[{"level":1,"text":"Các sơ đồ giúp mô tả và chia sẻ tình huống một cách trực quan dễ dàng, và không có gì ngạc nhiên khi mỗi ngành nghề đều có vô số lựa chọn sơ đồ"},{"level":1,"text":"Phần mềm vẽ sơ đồ hiện đại có các mẫu tích hợp sẵn giúp việc tạo sơ đồ còn dễ dàng hơn"},{"level":1,"text":"Lựa chọn các sơ đồ phổ biến"},{"level":2,"text":"Biểu đồ Gantt (Gantt Chart)"},{"level":2,"text":"Một loại biểu đồ thanh thể hiện thời gian trên trục hoành và danh sách các công việc hoặc hoạt động trên trục tung, với các thanh biểu thị thời gian mỗi hoạt động sẽ diễn ra"},{"level":2,"text":"Biểu đồ Gantt được dùng cho việc lập lịch nâng cao"},{"level":2,"text":"Lưu đồ (Flowchart)"},{"level":2,"text":"Lưu đồ còn được gọi là luồng quy trình (process flow) hoặc sơ đồ quy trình (process diagrams)"},{"level":2,"text":"Trực quan hóa một quy trình và có thể nén các hướng dẫn công việc phức tạp thành vài biểu đồ"},{"level":2,"text":"Lưu đồ dễ đọc và dễ hiểu; việc loại bỏ hoặc thay đổi các bước được thể hiện cực kỳ dễ dàng bằng lưu đồ"},{"level":2,"text":"Cây quyết định (Decision Tree)"},{"level":2,"text":"Mô tả một quy trình có thể có nhiều quyết định và nhiều kết quả"},{"level":2,"text":"Sử dụng loại biểu đồ này khi một quyết định duy nhất đòi hỏi cân nhắc nhiều yếu tố"},{"level":2,"text":"Sơ đồ luồng dữ liệu (Data Flow Diagram - DFD)"},{"level":2,"text":"Cho thấy cách thông tin lưu chuyển qua một quy trình hoặc hệ thống"},{"level":2,"text":"Loại sơ đồ này hoạt động đặc biệt hiệu quả với đối tượng gồm cả người có chuyên môn kỹ thuật và phi kỹ thuật"},{"level":2,"text":"Sơ đồ tư duy (Mind Map)"},{"level":2,"text":"Trực quan hóa các danh mục thông tin xoay quanh một chủ đề duy nhất, rất tốt cho việc điều phối các hoạt động động não"},{"level":2,"text":"Sơ đồ tư duy rất tốt cho việc điều phối các hoạt động động não, suy nghĩ thấu đáo các vấn đề hoặc tổng hợp thông tin"},{"level":2,"text":"Tứ phân (Quadrant)"},{"level":2,"text":"Một lưới bốn ô, mỗi trục đặt một yếu tố, và mỗi ô đại diện cho một tổ hợp cao-thấp của hai yếu tố"},{"level":2,"text":"Sơ đồ tứ phân là công cụ tuyệt vời để nhanh chóng gán giá trị hoặc thể hiện mức độ ưu tiên tương đối của nhiều lựa chọn"}]},{"id":"g56","part":6,"title":"Công cụ cộng tác (Collaboration Tools)","blocks":[{"level":1,"text":"Các quản lý dự án giúp tổ chức và dẫn dắt các nhóm người"},{"level":1,"text":"Các công cụ cộng tác cho phép mọi người làm việc trên tài liệu ở một nơi và thời điểm giúp họ làm việc hiệu quả nhất"},{"level":1,"text":"Là một quản lý dự án, bạn nên nhận biết và biết khi nào cần triển khai:"},{"level":2,"text":"Phần mềm chỉnh sửa đa tác giả (Multi-authoring Editing Software)"},{"level":2,"text":"Cho phép nhiều người dùng cập nhật cùng một tệp đồng thời"},{"level":2,"text":"Tệp cũng được cập nhật cho tất cả người dùng khi có ai đó cập nhật nó"},{"level":2,"text":"Nhược điểm (Disadvantage)"},{"level":2,"text":"Định dạng này trao cho mọi người quyền chỉnh sửa kết quả cuối cùng, vì vậy bạn có nguy cơ bị thay đổi và xóa trái phép"},{"level":2,"text":"Nền tảng chia sẻ tệp (File Sharing Platforms)"},{"level":2,"text":"Cho phép đăng một tệp tại một vị trí duy nhất và cấp quyền truy cập cho một hoặc nhiều người dùng"},{"level":2,"text":"Bạn cũng có thể quản lý quyền để kiểm soát các tệp mà mọi người có thể truy cập, chỉnh sửa và tải về"},{"level":2,"text":"Chia sẻ tệp với người bên ngoài công ty khiến tài sản của công ty bị lộ trước các tác nhân xấu tiềm ẩn"},{"level":2,"text":"Luôn đảm bảo các thực hành chia sẻ tệp đáp ứng yêu cầu bảo mật của tổ chức"},{"level":2,"text":"Nền tảng quy trình công việc và chữ ký điện tử (Workflow and e-Signature Platforms)"},{"level":2,"text":"Hệ thống quản lý quy trình công việc cho phép ký tài liệu bằng kết nối Internet và thiết bị điện tử, như điện thoại thông minh, máy tính bảng hoặc máy tính xách tay"},{"level":2,"text":"Một số người dùng có thể không thoải mái với hợp đồng điện tử"},{"level":2,"text":"Cơ sở tri thức (Knowledge Bases)"},{"level":2,"text":"Wiki"},{"level":2,"text":"Sản phẩm cộng tác nơi mọi người có kiến thức đều có thể đóng góp nội dung"},{"level":2,"text":"Cơ sở tri thức (Knowledge Base)"},{"level":2,"text":"Được tuyển chọn kỹ hơn wiki, và các tác giả cụ thể đóng góp vào cơ sở tri thức, bao quát các chủ đề nhất định"},{"level":2,"text":"Bảng trắng (Whiteboards)"},{"level":2,"text":"Tạo một không gian sáng tạo ảo trông rất giống bảng trắng vật lý, cung cấp một khung vẽ trống mà bất kỳ ai cũng có thể dùng để hoàn thành bất kỳ công việc sáng tạo nào"},{"level":2,"text":"Bảng trắng ảo cho phép nhiều người truy cập và sự thoải mái hơn cho người dùng, và bạn thậm chí có thể lưu một bản sao của bảng trắng ảo"}]},{"id":"g57","part":6,"title":"Công cụ giao tiếp (Communication Tools)","blocks":[{"level":1,"text":"Email"},{"level":2,"text":"Một công nghệ giao tiếp không đồng bộ phổ biến"},{"level":2,"text":"Email được dùng để tương tác với người bên ngoài và bên trong tổ chức trên cùng một kênh"},{"level":2,"text":"Ưu điểm (Advantages)"},{"level":2,"text":"Tin nhắn đến người nhận nhanh chóng"},{"level":2,"text":"Lưu giữ hồ sơ lịch sử"},{"level":2,"text":"Phù hợp cho các tin nhắn ưu tiên thấp, tin nhắn dài và giao tiếp hàng loạt"},{"level":2,"text":"Email không phải là công cụ thích hợp để phản hồi ngay lập tức"},{"level":1,"text":"Chat/Nhắn tin tức thì (Chat/Instant Messaging)"},{"level":2,"text":"Một loại dịch vụ nhắn tin nơi tin nhắn được trao đổi giữa hai hoặc nhiều bên qua kết nối Internet"},{"level":2,"text":"Chat có thể không hoạt động cùng lúc với người bên trong và bên ngoài tổ chức"},{"level":2,"text":"Ưu điểm (Advantages)"},{"level":2,"text":"Lưu giữ hồ sơ lịch sử"},{"level":2,"text":"Mang tính trò chuyện và không chính thức"},{"level":2,"text":"Hướng tới thời gian thực hơn"},{"level":2,"text":"Dùng cho các cuộc trò chuyện ngắn"},{"level":2,"text":"Không dùng chat khi cần ghi lại hồ sơ lịch sử hoặc chia sẻ tin nhắn dài"},{"level":1,"text":"Nhắn tin hay dịch vụ tin nhắn ngắn (Texting or Short Message Services - SMS)"},{"level":2,"text":"Một hình thức giao tiếp thường được truyền qua mạng di động nhưng cũng có thể được truyền qua Internet"},{"level":2,"text":"Các doanh nghiệp dùng tin nhắn SMS cho các tin nhắn văn bản ngắn, một chiều"},{"level":1,"text":"Trò chuyện trực tiếp (Talking Face-To-Face)"},{"level":2,"text":"Các cuộc họp nơi hai hoặc nhiều người ở trong cùng một phòng cùng lúc, trao đổi thông tin và ý tưởng"},{"level":2,"text":"Các cuộc họp hiệu quả khi thảo luận các chủ đề nhạy cảm và xây dựng mối quan hệ"},{"level":1,"text":"Điện thoại (Telephone)"},{"level":2,"text":"Một hình thức giao tiếp đồng bộ vượt qua ranh giới địa lý"},{"level":2,"text":"Điện thoại cố định (Landline)"},{"level":2,"text":"Điện thoại được đấu nối cứng vào tòa nhà"},{"level":2,"text":"VoIP (Thoại qua giao thức Internet - Voice over Internet Protocol)"},{"level":2,"text":"Người dùng nhận một số điện thoại truyền thống và dùng máy điện thoại để thực hiện cuộc gọi"},{"level":2,"text":"Di động (Cellular)"},{"level":2,"text":"Người dùng nhận số điện thoại tiêu chuẩn và truyền giọng nói qua các trạm thu phát sóng di động"},{"level":1,"text":"Video và hội nghị video (Video and Videoconference)"},{"level":2,"text":"Kết hợp khả năng nhìn thấy của các cuộc họp trực tiếp và cuộc gọi điện thoại để tạo ra một cuộc họp hoàn toàn trực tuyến"},{"level":2,"text":"Hội nghị video sử dụng phần mềm chuyên dụng"},{"level":2,"text":"Người dùng cần truy cập Internet ổn định, tai nghe và camera"},{"level":1,"text":"Mạng xã hội doanh nghiệp (Enterprise Social Media)"},{"level":2,"text":"Mạng giao tiếp nội bộ khuyến khích kết nối P2P và giọng điệu trò chuyện"},{"level":2,"text":"Mạng xã hội doanh nghiệp có thể là công cụ để nhân viên kết nối và giao tiếp với nhau"},{"level":2,"text":"Không dùng mạng xã hội doanh nghiệp để tương tác với người bên ngoài tổ chức"},{"level":2,"text":"Nội dung mạng xã hội doanh nghiệp thường ngắn và nông"}]},{"id":"g58","part":6,"title":"Các thành phần của kế hoạch giao tiếp (Elements of a Communication Plan)","blocks":[{"level":1,"text":"Tạo một kế hoạch chính thức giúp giảm chi phí gián tiếp (overhead) và đơn giản hóa các hoạt động quản lý dự án"},{"level":1,"text":"Kế hoạch giao tiếp (Communication Plan)"},{"level":2,"text":"Chiến lược được ghi thành văn bản, phác thảo cách các bên liên quan và thành viên nhóm sẽ nhận được cập nhật dự án"},{"level":2,"text":"Các kế hoạch giao tiếp cũng khác nhau về độ sâu và mức độ trang trọng, nhưng mọi kế hoạch đều nên được ghi thành văn bản để tạo sự rõ ràng và quản lý kỳ vọng cho những người liên quan"},{"level":2,"text":"8 thành phần phổ biến của kế hoạch giao tiếp"},{"level":2,"text":"Mục tiêu giao tiếp (Communication Goal)"},{"level":2,"text":"Xác định mục đích của kế hoạch giao tiếp trước khi nó được tạo ra"},{"level":2,"text":"Các bên liên quan (Stakeholders)"},{"level":2,"text":"Xác định từng bên liên quan theo tên và ghi lại thông tin hữu ích, như chức danh, mối quan hệ với dự án, múi giờ, vị trí và phương thức liên lạc ưa thích"},{"level":2,"text":"Thành viên nhóm (Team Member)"},{"level":2,"text":"Liệt kê tên, công việc, múi giờ, vị trí và phương thức liên lạc ưa thích của mỗi thành viên nhóm"},{"level":2,"text":"Hiện vật (Artifact)"},{"level":2,"text":"Xác định các hiện vật giao tiếp khác nhau cần thiết để đáp ứng nhu cầu của các bên liên quan và thành viên nhóm"},{"level":2,"text":"Kênh giao tiếp (Communication Channel)"},{"level":2,"text":"Chọn kênh giao tiếp tốt nhất cho mỗi hiện vật"},{"level":2,"text":"Người nhận (Recipient)"},{"level":2,"text":"Xác định ai sẽ nhận thông tin giao tiếp"},{"level":2,"text":"Tần suất (Frequency)"},{"level":2,"text":"Xác định tần suất mỗi thông tin giao tiếp cần được chia sẻ"},{"level":2,"text":"Kết quả (Outcome)"},{"level":2,"text":"Xác định điều gì phải xảy ra khi giao tiếp"}]},{"id":"g59","part":6,"title":"Xây dựng kế hoạch giao tiếp (Develop a Communication Plan)","blocks":[{"level":1,"text":"Một kế hoạch giao tiếp định hình phong cách cho phần còn lại của dự án bằng cách thiết lập kỳ vọng với các bên liên quan và thành viên nhóm"},{"level":1,"text":"Tính minh bạch và nhịp độ (cadence) rất quan trọng trong một kế hoạch giao tiếp"},{"level":1,"text":"Các bước xây dựng kế hoạch giao tiếp"},{"level":2,"text":"Xác định các bên liên quan"},{"level":2,"text":"Liệt kê những người cần giao tiếp thường xuyên trong suốt dự án"},{"level":2,"text":"Ghi lại tên, chức danh, mối quan hệ với dự án và các yêu cầu của bên liên quan"},{"level":2,"text":"Xác định các sở thích giao tiếp"},{"level":2,"text":"Tìm hiểu cách mọi người muốn được tương tác"},{"level":2,"text":"Xác định loại thông tin, mức độ chi tiết được cung cấp và cách tiếp nhận thông tin"},{"level":2,"text":"Tạo kế hoạch giao tiếp, chia sẻ và hoàn thiện kế hoạch"},{"level":2,"text":"Sử dụng các thành phần của kế hoạch giao tiếp"},{"level":2,"text":"Mục tiêu giao tiếp (Communication Goal)"},{"level":2,"text":"Các bên liên quan (Stakeholders)"},{"level":2,"text":"Thành viên nhóm (Team members)"},{"level":2,"text":"Hiện vật (Artifact)"},{"level":2,"text":"Kênh giao tiếp (Communication Channel)"},{"level":2,"text":"Người nhận (Recipient)"},{"level":2,"text":"Tần suất (Frequency)"},{"level":2,"text":"Kết quả (Outcome)"},{"level":2,"text":"Sử dụng mẫu (template) để giúp sắp xếp thông tin và đảm bảo mọi thứ được bao quát"},{"level":2,"text":"Mẫu có thể đơn giản và thẳng thắn"},{"level":2,"text":"Bước chia sẻ và hoàn thiện kế hoạch bao gồm việc gửi bản nháp cho mọi người liên quan"},{"level":2,"text":"Lên lịch cuộc họp"},{"level":2,"text":"Lên lịch các công việc cần thiết để chuẩn bị cho các cuộc họp"},{"level":2,"text":"Kế hoạch giao tiếp bao trùm các hoạt động từ một tài liệu tĩnh đến một kế hoạch hành động"},{"level":2,"text":"Sửa đổi kế hoạch"},{"level":2,"text":"Xem lại các mục tiêu của kế hoạch giao tiếp để đảm bảo sự thống nhất liên tục với kế hoạch"},{"level":1,"text":"Các thực hành tốt nhất khi tạo và triển khai kế hoạch giao tiếp"},{"level":2,"text":"Việc lập kế hoạch được thực hiện để có sự ngăn nắp, mà còn dễ dàng hơn"},{"level":2,"text":"Kế hoạch giao tiếp chuẩn hóa lịch giao tiếp và các hiện vật"},{"level":2,"text":"Điều chỉnh kế hoạch giao tiếp cho phù hợp với phong cách và tần suất của đối tượng"},{"level":2,"text":"Hỏi nhóm về cuộc họp hoặc cách giao tiếp ưa thích"}]},{"id":"g60","part":6,"title":"Xây dựng kế hoạch leo thang (Build an Escalation Plan)","blocks":[{"level":1,"text":"Kế hoạch leo thang (Escalation Plan)"},{"level":2,"text":"Còn được gọi là \"ma trận leo thang\" (escalation matrix), kế hoạch này mô tả các kịch bản sự cố có thể xảy ra trong dự án của bạn và cách bạn có thể giải quyết chúng"},{"level":1,"text":"Kế hoạch leo thang rất quan trọng để đảm bảo các vấn đề của dự án được giải quyết nhanh chóng và hiệu quả"},{"level":1,"text":"Mọi nhật ký (log) được tạo ra sau này đều phản ánh ý định của kế hoạch"},{"level":1,"text":"Kế hoạch leo thang được lập trong giai đoạn Initiation của dự án"},{"level":1,"text":"4 thành phần chính của một kế hoạch leo thang"},{"level":2,"text":"Hạng mục (Category)"},{"level":2,"text":"Mô tả loại leo thang"},{"level":2,"text":"Cấp độ (Level)"},{"level":2,"text":"Cho biết thứ tự leo thang"},{"level":2,"text":"Người chịu trách nhiệm (Owner)"},{"level":2,"text":"Người cần liên hệ khi đạt đến bất kỳ cấp độ nào"},{"level":2,"text":"Điều kiện kích hoạt (Trigger)"},{"level":2,"text":"Mô tả các điều kiện khởi phát việc leo thang"},{"level":1,"text":"Leo thang (Escalation) là một kỹ thuật giải quyết vấn đề"},{"level":1,"text":"Việc leo thang phù hợp là điều thiết yếu cho quản lý dự án hiệu quả"}]},{"id":"g61","part":6,"title":"Duy trì hồ sơ giao tiếp (Maintain Communication Records)","blocks":[{"level":1,"text":"Rất quan trọng khi đánh giá và cập nhật kế hoạch quản lý hồ sơ (records management plan) mỗi khi bạn tạo hoặc sửa đổi kế hoạch giao tiếp (communication plan)"},{"level":1,"text":"Hãy xem xét các yếu tố sau khi duy trì hồ sơ giao tiếp"},{"level":2,"text":"Bảo mật (Security)"},{"level":2,"text":"An ninh giao tiếp (Communication security) đóng vai trò then chốt trong việc bảo vệ thông tin dự án"},{"level":2,"text":"3 loại dữ liệu khác nhau"},{"level":2,"text":"Dữ liệu công khai (Public Data)"},{"level":2,"text":"Không hạn chế"},{"level":2,"text":"Dữ liệu mật (Confidential Data)"},{"level":2,"text":"Quyền truy cập hạn chế và chỉ dành cho người dùng được ủy quyền dựa trên vai trò"},{"level":2,"text":"Dữ liệu tối mật (Critical Data)"},{"level":2,"text":"Tuyệt mật và quyền truy cập bị hạn chế nghiêm ngặt"},{"level":2,"text":"Khi tạo các thông điệp giao tiếp của dự án, hãy đảm bảo bản chất của thông tin phù hợp với đối tượng nhận dự định"},{"level":2,"text":"Lưu trữ (Archiving)"},{"level":2,"text":"Lưu trữ giao tiếp (Communication archiving) quy định cách các tài liệu dự án được lưu trữ, bao gồm lưu cái gì, lưu ở đâu và lưu trong bao lâu"},{"level":2,"text":"Tuân thủ chính sách lưu giữ hồ sơ (records retention policy) của tổ chức và các yêu cầu an ninh thông tin"},{"level":2,"text":"Văn phòng quản lý dự án (PMO) duy trì một kho lưu trữ tập trung của mọi dự án đã hoàn thành"},{"level":2,"text":"Các kho lưu trữ giúp xác định các thực tiễn tốt nhất và bài học kinh nghiệm (lessons learned)"},{"level":2,"text":"Kho lưu trữ dự án cũng là nguồn dữ liệu phân tích, nơi các PMO xem xét dữ liệu để xác định xu hướng trong phạm vi chức năng của họ"},{"level":2,"text":"Kiểm toán viên tuân thủ (Compliance auditors) xem xét các kho lưu trữ để kiểm toán các tiêu chuẩn và quy trình của tổ chức"},{"level":2,"text":"Các kho lưu trữ cũng chứa các hồ sơ cần thiết để tuân thủ pháp lý"},{"level":2,"text":"Hồ sơ lựa chọn nhà cung cấp (Vendor Selection Records)"},{"level":2,"text":"Hợp đồng đã ký kết (Finalized Contracts)"},{"level":2,"text":"Tài liệu đánh giá (Evaluation Materials)"},{"level":2,"text":"Hồ sơ dự án chính xác là yếu tố then chốt để bảo vệ công ty trước các vụ kiện tụng tiềm tàng"},{"level":2,"text":"Tính toàn vẹn (Integrity)"},{"level":2,"text":"Tính toàn vẹn của giao tiếp (Communication integrity) là khi các thông điệp được chia sẻ thực sự khớp với thực tế"},{"level":2,"text":"Giao tiếp hiệu quả trong dự án đòi hỏi phải ghi nhận, tập trung và phản ánh đúng tiến độ thực tế của dự án"},{"level":2,"text":"Việc ghi nhận và chia sẻ biên bản họp cũng như các tiến độ, quyết định đáng chú ý trong tài liệu dự án đảm bảo tính toàn vẹn"},{"level":2,"text":"Việc tập trung thông tin từ nhiều nền tảng khác nhau, như nền tảng lập kế hoạch, email, chat và cuộc họp, thành một sản phẩm giao tiếp tóm tắt giúp theo dõi các quyết định quan trọng"},{"level":1,"text":"Các sản phẩm giao tiếp (Communication artifacts) phải luôn phản ánh sự thật và tiến độ thực tế của dự án, vì niềm tin vào dữ liệu là điều thiết yếu"},{"level":1,"text":"Các lỗi cố ý và vô ý đều có thể làm tổn hại tính toàn vẹn của giao tiếp. Triển khai thiết kế giải pháp (Implementing Solution Design)"}]},{"id":"g62","part":7,"title":"Triển khai thiết kế giải pháp (Implementing Solution Design)","blocks":[{"level":1,"text":"Đảm bảo rằng các phần mềm bổ sung mới tương thích với các sản phẩm hiện có"},{"level":1,"text":"Thiết kế cấp cao (High-Level Design - HLD)"},{"level":2,"text":"Cung cấp cho các bên liên quan (stakeholders) cái nhìn tổng quan về cách tiếp cận dự án và hình ảnh giải pháp cuối cùng sẽ như thế nào"},{"level":1,"text":"Thiết kế cấp thấp (Low-Level Design - LLD)"},{"level":2,"text":"Đưa ra các hướng dẫn triển khai mà nhóm có thể làm theo để thực hiện dự án"},{"level":1,"text":"Quy luật lợi ích giảm dần (Diminishing Returns)"},{"level":2,"text":"Chỉ điểm mà tại đó nguồn lực hoặc nỗ lực đầu tư thêm sẽ chỉ mang lại những cải thiện ngày càng nhỏ hoặc không đáng kể cho kết quả dự án"},{"level":1,"text":"Nguyên tắc Pareto (Pareto Principle)"},{"level":2,"text":"Phát biểu rằng khoảng 80% kết quả của dự án thường bắt nguồn từ 20% nỗ lực hoặc hoạt động"},{"level":1,"text":"Hạ tầng công nghệ thông tin (IT Infrastructure)"},{"level":2,"text":"Chỉ hệ thống liên kết của phần cứng, phần mềm, mạng và trung tâm dữ liệu"},{"level":2,"text":"Giúp tổ chức quản lý và cung cấp dịch vụ công nghệ thông tin một cách hiệu quả, hỗ trợ hoạt động kinh doanh, đồng thời tạo điều kiện cho giao tiếp và lưu trữ dữ liệu"},{"level":1,"text":"Phân loại và xử lý dữ liệu (Data classification and handling) trong quản lý dự án bao gồm việc phân loại, sắp xếp và quản lý dữ liệu dự án một cách có hệ thống"},{"level":2,"text":"Việc này dựa trên độ nhạy cảm, tính bảo mật và các yêu cầu pháp lý của dữ liệu dự án"},{"level":1,"text":"An ninh vận hành (Operational Security - OpSec)"},{"level":2,"text":"Chỉ các biện pháp và thực tiễn được triển khai để bảo vệ tính bảo mật, tính toàn vẹn và tính sẵn sàng của nguồn lực, dữ liệu và hệ thống dự án bằng cách giảm thiểu rủi ro, triển khai kiểm soát truy cập, giám sát hoạt động và ứng phó với các sự cố bảo mật"}]},{"id":"g63","part":7,"title":"Tổng quan về thiết kế giải pháp (Solution Design Overview)","blocks":[{"level":1,"text":"Thiết kế giải pháp (Solution Design)"},{"level":2,"text":"Nhằm tối ưu hóa một dự án trong giới hạn của môi trường vận hành của nó, và bao gồm việc thu thập các yêu cầu về kiến trúc và thiết kế, yêu cầu kiểm thử, rủi ro kỹ thuật, và phân tích các đánh đổi (tradeoffs)"},{"level":1,"text":"Quy trình thiết kế giải pháp bao gồm việc tạo ra hai tài liệu"},{"level":2,"text":"Thiết kế cấp cao (High-level Design - HLD)"},{"level":2,"text":"Được tạo ra trong giai đoạn phân tích (analysis phase) của quy trình SDLC, và nó đánh giá tính khả thi kỹ thuật"},{"level":2,"text":"HLD định nghĩa các tham số không thể thương lượng và các yêu cầu phi chức năng (non-functional requirements - NFRs), và được dùng để lựa chọn giải pháp"},{"level":2,"text":"Thiết kế cấp thấp (Low-level Design - LLD)"},{"level":2,"text":"Được tạo ra trong giai đoạn thiết kế (design phase) của quy trình SDLC, và là tài liệu ra quyết định kỹ thuật để làm rõ chi tiết dự án"},{"level":2,"text":"LLD đóng vai trò là tài liệu tham khảo để tạo công việc, dù sử dụng cấu trúc phân rã công việc (work breakdown structure - WBS) hay các câu chuyện người dùng (user stories)"},{"level":1,"text":"Sản phẩm cuối cùng là một bản thiết kế tổng thể (blueprint) cho dự án, mà nhóm dự án sẽ xây dựng dựa trên HLD và LLD"},{"level":2,"text":"Bản thiết kế tổng thể (Blueprint)"},{"level":2,"text":"Đây là thứ mà nhóm dự án sẽ xây dựng dựa trên hai tài liệu này, HLD và LLD"},{"level":1,"text":"Quy trình thiết kế giải pháp nhằm giảm thiểu chi phí thay đổi trong các dự án"},{"level":1,"text":"Trong trường hợp nhóm dự án phát hiện ra rằng đến tháng thứ tám của dự án, phần mềm không đáp ứng một yêu cầu quan trọng, điều này có thể dẫn đến tổn thất đáng kể về thời gian và tiền bạc"},{"level":1,"text":"Việc thiết kế giải pháp xác định nhu cầu và so sánh các lựa chọn khác nhau từ sớm là rất quan trọng để tìm ra một tập hợp sản phẩm được đồng thuận, có thể giảm thiểu đáng kể các rủi ro này"},{"level":1,"text":"Sự hợp tác trong thiết kế giải pháp tạo dựng niềm tin vào dự án"},{"level":1,"text":"Thiết kế giải pháp làm giảm rủi ro dự án trong môi trường kinh doanh"},{"level":1,"text":"Hãy bắt đầu với mục tiêu cuối cùng trong đầu bằng cách suy nghĩ về mọi thứ từ sớm và tạo ra các thiết kế cấp cao và cấp thấp của bạn"}]},{"id":"g64","part":7,"title":"Ví dụ về thiết kế giải pháp (Solution Design Example)","blocks":[{"level":1,"text":"Yêu cầu chức năng (Functional Requirements)"},{"level":2,"text":"Các tính năng do doanh nghiệp yêu cầu, như tính năng sản phẩm, giao diện người dùng, quy trình quản trị, và hỗ trợ triển khai hoặc đào tạo"},{"level":1,"text":"Yêu cầu phi chức năng (Nonfunctional Requirements - NFRs)"},{"level":2,"text":"Các thuộc tính của hệ thống thể hiện khả năng vận hành của nó, thường được gọi là các \"ilities\" của phần mềm"},{"level":2,"text":"Khả năng mở rộng (Scalability) là một ví dụ điển hình của NFR"},{"level":2,"text":"Ví dụ về NFR"},{"level":2,"text":"Tính khả dụng cho người dùng (Usability)"},{"level":2,"text":"Mức độ thân thiện với người dùng của nó"},{"level":2,"text":"Khả năng mở rộng (Scalability)"},{"level":2,"text":"Giải pháp có thể dễ dàng mở rộng hoặc thu hẹp như thế nào khi nhu cầu thay đổi"},{"level":2,"text":"Tính sẵn sàng/Độ tin cậy (Availability/Reliability)"},{"level":2,"text":"Nó hoạt động trong bao lâu trong một khoảng thời gian nhất định"},{"level":2,"text":"Bảo mật (Security)"},{"level":2,"text":"Giải pháp và tài sản của công ty được bảo vệ tốt như thế nào"},{"level":2,"text":"Tính dễ bảo trì (Maintainability)"},{"level":2,"text":"Nó có thể dễ dàng được thay đổi hoặc chỉnh sửa về sau như thế nào"},{"level":2,"text":"Tính dễ mở rộng (Extensibility)"},{"level":2,"text":"Dễ dàng thêm tính năng mới như thế nào mà không làm thay đổi những gì đã có"},{"level":2,"text":"Tính di động/Tương thích (Portability/Compatibility)"},{"level":2,"text":"Giải pháp hoạt động tốt như thế nào trong môi trường hiện có"},{"level":2,"text":"Tuân thủ (Compliance)"},{"level":2,"text":"Nhu cầu giải pháp phải tuân thủ các yêu cầu pháp lý liên quan"},{"level":1,"text":"Việc áp dụng thiết kế giải pháp giúp đánh giá các đánh đổi liên quan"},{"level":1,"text":"Trong các tình huống kinh doanh phức tạp hơn, hãy sử dụng các tiêu chí và kỹ thuật lập hồ sơ tinh vi hơn"},{"level":1,"text":"Các yêu cầu chức năng và phi chức năng trong thiết kế giải pháp thực sự tập trung vào các \"ilities\" của phần mềm hoặc thứ đang được xây dựng"}]},{"id":"g65","part":7,"title":"Cách tiếp cận thiết kế giải pháp (Solution Design Approach)","blocks":[{"level":1,"text":"Một số yếu tố môi trường doanh nghiệp (enterprise environmental factors) khi tạo thiết kế giải pháp"},{"level":2,"text":"Yêu cầu chức năng (Functional requirements)"},{"level":2,"text":"Yêu cầu phi chức năng (Non-functional requirements)"},{"level":2,"text":"Ràng buộc (Constraints)"},{"level":2,"text":"Sản phẩm phần mềm (Software products)"},{"level":2,"text":"Yêu cầu phần cứng (Hardware requirements)"},{"level":1,"text":"Kiến trúc sư cũng phải thừa nhận các giới hạn khi thiết kế hệ thống, xem chi phí, lịch trình và ranh giới phạm vi của dự án như các ràng buộc"},{"level":1,"text":"Yêu cầu phần cứng phải được định nghĩa và thiết kế phù hợp với chiến lược phần cứng của công ty"},{"level":1,"text":"Các yếu tố môi trường có thể áp đặt các mục tiêu tiêu chuẩn và mục tiêu theo tình huống, trong đó một số yếu tố chỉ mang tính tạm thời hoặc đặc thù cho một dự án"},{"level":1,"text":"Vì thiết kế giải pháp liên quan đến việc tối ưu hóa giải pháp, nhóm thiết kế cũng nên xem xét nhiều lựa chọn"},{"level":1,"text":"Việc cân bằng thời gian và tiền bạc đầu tư vào quy trình thiết kế giải pháp so với lợi ích của dự án là điều thiết yếu"},{"level":1,"text":"Mục tiêu của thiết kế giải pháp không phải là giải quyết mọi vấn đề, mà là hiểu đủ để tự tin rằng giải pháp đáp ứng các yêu cầu"},{"level":1,"text":"15 thành phần của tài liệu thiết kế giải pháp"},{"level":2,"text":"Tổng quan dự án/giải pháp (Project/Solution Overview)"},{"level":2,"text":"Thành phần này cung cấp tóm tắt ngắn gọn về dự án hoặc giải pháp mà tài liệu đề cập"},{"level":2,"text":"Đối tượng mục tiêu (Intended Audience)"},{"level":2,"text":"Xác định rõ ràng đối tượng mục tiêu của tài liệu"},{"level":2,"text":"Mục đích (Purpose)"},{"level":2,"text":"Thành phần này mô tả cách đối tượng sẽ sử dụng tài liệu"},{"level":2,"text":"Tài liệu tham khảo (References)"},{"level":2,"text":"Thành phần này liệt kê bất kỳ tài liệu nào khác mà đối tượng mục tiêu có thể cần tham khảo, chẳng hạn như điều lệ dự án (project charter) hoặc tuyên bố phạm vi (scope statement)"},{"level":2,"text":"Bảng thuật ngữ (Glossary)"},{"level":2,"text":"Các tài liệu kỹ thuật thường chứa các thuật ngữ và chữ viết tắt không quen thuộc, và thành phần này cung cấp định nghĩa cho các thuật ngữ đó"},{"level":2,"text":"Tóm tắt hệ thống hiện tại (Current System Summary)"},{"level":2,"text":"Thành phần này cung cấp tóm tắt về hệ thống hiện có và hiệu suất của nó, hoặc cách mọi thứ đang được thực hiện hiện nay"},{"level":2,"text":"Chi tiết yêu cầu chức năng (Detailed Functional Requirements)"},{"level":2,"text":"Thành phần này mô tả rõ ràng các yêu cầu kinh doanh và kỳ vọng của các bên liên quan, mà nhóm sẽ dùng để xây dựng các bài kiểm thử"},{"level":2,"text":"Chi tiết yêu cầu phi chức năng (Non-Functional Requirement Details)"},{"level":2,"text":"Thành phần này mô tả các yêu cầu phi chức năng mà dự án phải đáp ứng, chẳng hạn như kỳ vọng về hiệu năng hệ thống, dựa vào đó nhóm sẽ tạo các bài kiểm thử hoặc yêu cầu"},{"level":2,"text":"Giả định và điều kiện tiên quyết (Assumptions and Prerequisites)"},{"level":2,"text":"Thành phần này liệt kê các điều kiện vận hành mà nhóm cần và giả định là đã có sẵn"},{"level":2,"text":"Thiết kế cấp cao (High-Level Design - HLD)"},{"level":2,"text":"Thành phần này bao gồm các phương tiện trực quan, như sơ đồ luồng quy trình và sơ đồ luồng dữ liệu, để mô tả các hệ thống và tích hợp"},{"level":2,"text":"Thiết kế cấp thấp (Low-Level Design - LLD)"},{"level":2,"text":"Thành phần này cung cấp thông tin kỹ thuật chi tiết về mọi thay đổi đề xuất đối với hệ thống"},{"level":2,"text":"Phân tích tác động (Impact Analysis)"},{"level":2,"text":"Thành phần này đánh giá giải pháp đề xuất sẽ tác động như thế nào đến môi trường hiện có, bao gồm mọi cập nhật hoặc thay đổi cần thiết để đảm bảo tính tương thích"},{"level":2,"text":"Ngoài phạm vi (Out-of-Scope)"},{"level":2,"text":"Thành phần này định nghĩa rõ ràng ranh giới của dự án và những gì không bao gồm trong giải pháp"},{"level":2,"text":"Rủi ro và giảm thiểu (Risks and Mitigation)"},{"level":2,"text":"Thành phần này ghi lại các rủi ro đã biết và phác thảo chiến lược giảm thiểu hiện tại, bao gồm mọi bài kiểm thử cần thiết hoặc các yếu tố chưa rõ tiềm tàng"},{"level":2,"text":"Phụ lục (Appendix)"},{"level":2,"text":"Thành phần tùy chọn này bao gồm mọi thông tin bổ sung nhưng có giá trị mà nhóm có thể thấy hữu ích"},{"level":1,"text":"Mẫu và các thành phần dùng cho tài liệu HLD và LLD có thể tương tự nhau với những điều chỉnh nhỏ"},{"level":2,"text":"HLD"},{"level":2,"text":"Khó có thể bao gồm tên thương hiệu phần mềm cụ thể"},{"level":2,"text":"LLD"},{"level":2,"text":"Rất chi tiết và cung cấp các cấu hình, thông số kỹ thuật cụ thể"}]},{"id":"g66","part":7,"title":"Thiết kế giải pháp trong dự án Agile (Solution Design in an Agile Project)","blocks":[{"level":1,"text":"Thiết kế giải pháp (Solution Design)"},{"level":2,"text":"Một quy trình đòi hỏi tài liệu đầy đủ"},{"level":2,"text":"Trong cách tiếp cận Waterfall, nó được hoàn thành ngay từ đầu"},{"level":2,"text":"Trong cách tiếp cận Agile, nó được hoàn thành trong mỗi vòng lặp (iteration)"},{"level":1,"text":"Nên dùng cách tiếp cận cân bằng kết hợp giá trị của Agile và Waterfall"},{"level":1,"text":"Bắt đầu với các NFR và các yêu cầu giải pháp không thể thương lượng, rồi dần mở rộng trong mỗi vòng lặp"},{"level":1,"text":"Câu chuyện người dùng (User Stories)"},{"level":2,"text":"Một định dạng phổ biến để diễn đạt các yêu cầu thiết kế trong bối cảnh Agile, trong khi các dự án Waterfall sử dụng một tài liệu duy nhất và dài dòng"},{"level":1,"text":"Phương pháp Agile tuân theo các vòng lặp thường kéo dài 1-4 tuần (sprint)"},{"level":1,"text":"Các nhóm Agile tự tổ chức hơn và có mức độ hiệu suất cao hơn so với các nhóm truyền thống"}]},{"id":"g67","part":7,"title":"Lợi ích giảm dần và nguyên tắc Pareto (Diminishing Returns and the Pareto Principle)","blocks":[{"level":1,"text":"Quy luật lợi ích giảm dần (Law of Diminishing Returns)"},{"level":2,"text":"Quy luật lợi ích giảm dần là một nguyên tắc kinh tế, nhưng nó có thể được áp dụng cho nhiều tình huống"},{"level":2,"text":"Một khoản đầu tư ban đầu nhỏ có thể dẫn đến sự gia tăng mạnh mẽ về năng suất hoặc giá trị"},{"level":2,"text":"Việc áp dụng quy luật lợi ích giảm dần vào tình huống của chúng ta cho phép xác định không phải mức đầu ra cao nhất có thể, mà là mức đầu ra có lợi nhuận cao nhất"},{"level":2,"text":"Trong thiết kế giải pháp, các kiến trúc sư cân bằng nhiều yêu cầu để tạo ra giải pháp tối ưu bằng cách dùng lợi ích giảm dần"},{"level":1,"text":"Nguyên tắc Pareto (Pareto Principle)"},{"level":2,"text":"Nguyên tắc Pareto, còn được gọi là \"quy tắc 80/20\" (80/20 rule), cho rằng 80% vấn đề có thể được giải quyết bằng cách xử lý 20% nguyên nhân của nó"}]},{"id":"g68","part":7,"title":"Hạ tầng công nghệ thông tin (IT Infrastructure)","blocks":[{"level":1,"text":"Kiến trúc sư chịu trách nhiệm tạo ra thiết kế giải pháp phải tính đến nhiều khái niệm CNTT khác nhau"},{"level":2,"text":"Mô hình điện toán (Computing Models)"},{"level":2,"text":"Yêu cầu hạ tầng (Infrastructure Requirements)"},{"level":2,"text":"Biện pháp bảo mật (Security Measures)"},{"level":1,"text":"Hạ tầng bao gồm nhiều thứ khác nhau"},{"level":2,"text":"Dịch vụ điện toán (Computing Services)"},{"level":2,"text":"Bao gồm toàn bộ hạ tầng CNTT, gồm phần cứng và phần mềm, cũng như các nhà cung cấp dịch vụ"},{"level":2,"text":"Kiến trúc đa tầng (Multi-tiered Architecture)"},{"level":2,"text":"Một thiết kế phần mềm mô-đun chia phần mềm thành các lớp hoặc tầng riêng biệt"},{"level":2,"text":"Tính mô-đun (Modularity) là một yêu cầu phi chức năng (NFR) phổ biến giúp tăng cường khả năng chống chịu của hệ thống"},{"level":2,"text":"Kiến trúc một tầng được dùng trong các môi trường sản xuất và kiểm thử nhỏ"},{"level":2,"text":"Thiết kế ba tầng bao gồm tầng trình diễn (presentation), tầng ứng dụng (application) và tầng dữ liệu (data)"},{"level":2,"text":"Mạng và kết nối (Networking and Connectivity)"},{"level":2,"text":"Chỉ cách các người dùng và thành phần khác nhau trong một hệ thống kết nối với nhau"},{"level":2,"text":"Nó bao gồm cấu hình mạng, giao thức, quy tắc truy cập và phần cứng như cáp, switch và router"},{"level":2,"text":"Mạng là một thành phần then chốt của bất kỳ dự án phần mềm nào"},{"level":2,"text":"Lưu trữ (Storage)"},{"level":2,"text":"Công nghệ vật lý cần một kế hoạch lưu trữ, bao gồm vị trí vật lý, kiểm soát nhiệt độ và kiểm soát độ ẩm"},{"level":2,"text":"Cơ sở dữ liệu (Databases)"},{"level":2,"text":"Cơ sở dữ liệu tổ chức thông tin điện tử thành các bảng có cấu trúc được thiết kế có chủ đích để các nhà phân tích và kỹ sư dễ dàng truy xuất và diễn giải"},{"level":2,"text":"Kho dữ liệu (Data Warehouses)"},{"level":2,"text":"Một cơ sở dữ liệu toàn diện được dùng cho mục đích phân tích và báo cáo"},{"level":2,"text":"Nó không thực hiện bất kỳ hành động nào"},{"level":2,"text":"Nó cung cấp dữ liệu cần thiết cho phân tích và báo cáo"},{"level":2,"text":"Quy trình kho dữ liệu làm sạch và định dạng dữ liệu"},{"level":2,"text":"Tài liệu (Documentation)"},{"level":2,"text":"Bao gồm toàn bộ dữ liệu và sơ đồ liên quan đến hạ tầng"},{"level":2,"text":"Sơ đồ mạng (Network diagrams)"},{"level":2,"text":"Thông tin máy chủ chi tiết (Detailed server information)"},{"level":2,"text":"Vị trí (Position)"},{"level":2,"text":"Hướng dẫn dịch vụ (Service directions)"},{"level":2,"text":"Địa chỉ (Addresses)"},{"level":2,"text":"Script (Scripts)"},{"level":2,"text":"Giao thức (Protocols)"},{"level":2,"text":"Giao tiếp (Communications)"},{"level":2,"text":"Bảo trì (Maintenance)"},{"level":2,"text":"Lịch biểu kết thúc vòng đời (End-of-life timetables)"},{"level":1,"text":"2 cách cung cấp dịch vụ điện toán"},{"level":2,"text":"Điện toán tại chỗ (On-premise Computing)"},{"level":2,"text":"Được thực hiện cục bộ"},{"level":2,"text":"Điện toán đám mây (Cloud Computing)"},{"level":2,"text":"Cần có kết nối internet"},{"level":2,"text":"Các mô hình điện toán đám mây khác nhau"},{"level":2,"text":"Hạ tầng dưới dạng dịch vụ (Infrastructure as a Service - IaaS)"},{"level":2,"text":"Cung cấp các nguồn tài nguyên điện toán cơ bản như máy chủ, mạng và lưu trữ"},{"level":2,"text":"Nền tảng dưới dạng dịch vụ (Platform as a Service - PaaS)"},{"level":2,"text":"Cung cấp các công cụ phát triển như môi trường phần mềm qua kết nối internet"},{"level":2,"text":"Phần mềm dưới dạng dịch vụ (Software as a Service - SaaS)"},{"level":2,"text":"Một ngăn xếp phần mềm hoàn chỉnh bao gồm hạ tầng, môi trường và sản phẩm mà người dùng cuối sẽ sử dụng"},{"level":2,"text":"Mọi thứ dưới dạng dịch vụ (Anything as a Service - XaaS)"},{"level":2,"text":"Bất kỳ dịch vụ điện toán đám mây nào, trong đó \"X\" đại diện cho một dịch vụ cụ thể"},{"level":2,"text":"XaaS đề cập đến khái niệm thuê ngoài một dịch vụ điện toán cho bên thứ ba"},{"level":1,"text":"Hoạch định nguồn lực doanh nghiệp (Enterprise Resource Planning - ERP)"},{"level":2,"text":"Được các doanh nghiệp mọi loại hình sử dụng để quản lý khối lượng công việc vận hành"},{"level":2,"text":"ERP cung cấp dữ liệu giá trị có thể dùng để cập nhật tiến độ dự án, chẳng hạn như phân bổ thời gian"},{"level":1,"text":"Hệ thống tài chính (Financial System)"},{"level":2,"text":"Một tập con của phần mềm ERP tập trung cụ thể vào các khía cạnh tài chính của tổ chức"},{"level":1,"text":"Quản lý quan hệ khách hàng (Customer Relationship Management - CRM)"},{"level":2,"text":"Được thiết kế để thiết lập và duy trì quan hệ khách hàng nhằm tăng doanh thu và lòng trung thành"},{"level":2,"text":"Từ góc độ quản lý dự án, nó rất có lợi vì có thể theo dõi xu hướng khiếu nại và các phản hồi khác của khách hàng, dùng để xác định các lĩnh vực trọng tâm cho các dự án hoặc nghiên cứu mới"},{"level":1,"text":"Hệ thống quản lý tài liệu điện tử (Electronic Document Management Systems - EDMS) và hệ thống quản lý hồ sơ (Record Management Systems - RMS)"},{"level":2,"text":"Các công ty có thể tạo, theo dõi và chia sẻ tài liệu bằng cách tự động hóa quy trình và áp dụng kiểm soát truy cập"},{"level":1,"text":"Hệ thống quản lý nội dung (Content Management System - CMS)"},{"level":2,"text":"Các hệ thống thân thiện với người dùng giúp đơn giản hóa các tác vụ phức tạp như tạo website và quản lý thông tin"}]});
